import{_ as u,o as l,c as t,a3 as s,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/unterricht-kataloge/andere-schulen.png",k=JSON.parse('{"title":"Herkunftsschulen außerhalb von NRW erfassen","description":"","frontmatter":{"title":"Herkunftsschulen außerhalb von NRW erfassen","source_pageid":341,"source_revision":4427},"headers":[],"relativePath":"schild3/unterricht-kataloge/andere-schulen-und-schulnummern-allgemeine-kataloge.md","filePath":"schild3/unterricht-kataloge/andere-schulen-und-schulnummern-allgemeine-kataloge.md"}'),i={name:"schild3/unterricht-kataloge/andere-schulen-und-schulnummern-allgemeine-kataloge.md"};function d(m,r,o,h,c,g){return l(),t("div",null,[...r[0]||(r[0]=[s('<h1 id="herkunftsschulen-außerhalb-von-nrw-erfassen" tabindex="-1">Herkunftsschulen außerhalb von NRW erfassen <a class="header-anchor" href="#herkunftsschulen-außerhalb-von-nrw-erfassen" aria-label="Permalink to &quot;Herkunftsschulen außerhalb von NRW erfassen&quot;">​</a></h1><p>Bereiten Sie die Herkunftseinträge für Schulen außerhalb von NRW vor. Dabei wird das Bundesland oder Herkunftsland über die dafür vorgesehenen Sammelschulnummern abgebildet.</p><p><a href="/bilder/unterricht-kataloge/andere-schulen.png"><img src="'+a+'" alt="Der Karteireiter Andere Schulen und Schulnummern listet die Pseudo-&quot;Schulnummern&quot; für die Herkunft aus anderen Bundesländern, ausgewählten Ländern und &quot;keine Schule&quot; auf." loading="lazy"></a></p><p><em>Der Karteireiter Andere Schulen und Schulnummern listet die Pseudo-&quot;Schulnummern&quot; für die Herkunft aus anderen Bundesländern, ausgewählten Ländern und &quot;keine Schule&quot; auf.</em></p><p>Kommen Schüler aus NRW zu Ihrer Schule, sind die Herkunftsschulen über ihre Schulnummern zu erfassen. Dieser werden über <em>Kataloge ➜ Schulen in NRW</em> verwaltet.</p><p>Bei allen anderen Schulen aus dem In- und Ausland werden keine konkreten Schulen mit Schulnummern erfasst.</p><p>Hierzu werden <em>Andere Schulen und Schulnummern</em> verwendet. Über <em>Kataloge</em> ➜ <strong>Andere Schulen und Schulnummern</strong> lassen sich mit dem <strong>+</strong> die zur Verfügung stehenden Einträge anwählen. Hierbei ist lediglich das Land, in dem die Herkunftsschule liegt, zu erfassen und für die Statistik relevant.</p><p>Kommt eine Schülerin oder ein Schüler aus dem <strong>Bundesland Bremen</strong>, wählen Sie <strong>Schule aus Bremen</strong> aus der vorgegebenen Liste. Übernehmen Sie die zugehörige Sammelschulnummer aus dem Katalog, statt sie aus einem Textbeispiel manuell zu übertragen.</p><p>Als mögliche Herkunftsländer gelten neben den Bundesländern auch aufgrund der Nähe und Grenzüberschreitung die Länder <em>Belgien</em>, <em>Luxemburg</em> und die <em>Niederlande</em>. Jeder dieser Herkunft wird fest eine Pseudo-Schulnummer zugeordnet. Alle anderen Herkunftsländer werden als das <em>Schule aus dem sonstigen Ausland</em> mit der Schulnummer <em>999000</em> aufgenommen.</p><p>Die <strong>Kurzbezeichnung</strong> und <strong>Offizielle Bezeichnung</strong> kann direkt übernommen werden. Da keine konkrete Schule bezeichnet wird, können weiteren Felder (Kürzel, Schulform sowie weitere Adressdaten, ...) frei bleiben.</p>',10),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Haben Schüler vor dem Besuch der Schulform "),e("em",null,"BK"),n(" oder "),e("em",null,"WBK"),n(" keine Schule besucht, ist dies über die Herkunftsart "),e("em",null,"Sonstige/keine Schule"),n(' zu erfassen. Diese ist mit der "Schulnummer" '),e("em",null,"980500"),n(" verbunden.")]),e("p",null,[n("In der Statistik wird diese Herkunftsart mit dem Kürzel "),e("em",null,"XS"),n(" erfasst. Gleiches gilt unter Verwendung dieser Schulnummer für die Herkunft aus Wehr-, Zivil- oder Bundesfreiwilligendienst mit dem Statistikkürzel "),e("em",null,"WZ"),n(".")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Andere_Schulen_und_Schulnummern_(Allgemeine_Kataloge)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 4427.")],-1)])])}const S=u(i,[["render",d]]);export{k as __pageData,S as default};
